/* ---- dosya: queue.c ---- */
#include "queue.h"

void queue_init(Queue *q) {
    q->front = 0;
    q->rear = 0;
    q->count = 0;
}

int queue_is_empty(const Queue *q) {
    return q->count == 0;
}

int queue_is_full(const Queue *q) {
    return q->count == QUEUE_CAPACITY;
}

int queue_enqueue(Queue *q, int value) {
    if (queue_is_full(q)) return 0;
    q->data[q->rear] = value;
    q->rear = (q->rear + 1) % QUEUE_CAPACITY;
    q->count++;
    return 1;
}

int queue_dequeue(Queue *q, int *out) {
    if (queue_is_empty(q)) return 0;
    *out = q->data[q->front];
    q->front = (q->front + 1) % QUEUE_CAPACITY;
    q->count--;
    return 1;
}

int queue_size(const Queue *q) {
    return q->count;
}


/* ---- dosya: main.c ---- */
#include <stdio.h>
#include "queue.h"

/* Girdi: ilk satirda islem sayisi n, ardindan n satir - her biri
   "E <deger>" (enqueue) veya "D" (dequeue).
   Cikti: her islem icin bir satir - enqueue basariliysa "OK", kapasite
   doluysa "FULL"; dequeue basariliysa deger, kuyruk bosşa "EMPTY".
   Sonda kuyrugun son boyutu. */

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Queue q;
    queue_init(&q);

    for (int i = 0; i < n; i++) {
        char op[4];
        if (scanf("%3s", op) != 1) return 0;
        if (op[0] == 'E') {
            int v;
            if (scanf("%d", &v) != 1) return 0;
            if (queue_enqueue(&q, v)) {
                printf("OK\n");
            } else {
                printf("FULL\n");
            }
        } else {
            int out;
            if (queue_dequeue(&q, &out)) {
                printf("%d\n", out);
            } else {
                printf("EMPTY\n");
            }
        }
    }

    printf("size=%d\n", queue_size(&q));
    return 0;
}


