typedef enum { SHAPE_CIRCLE, SHAPE_RECT } ShapeTag;

typedef struct {
    int radius;
} Circle;

typedef struct {
    int width;
    int height;
} Rect;

typedef struct {
    ShapeTag tag;
    union {
        Circle circle;
        Rect rect;
    } data;
} Shape;

static long shape_area(const Shape *s) {
    if (s->tag == SHAPE_CIRCLE) {
        return 3L * s->data.circle.radius * s->data.circle.radius;
    } else {
        return (long)s->data.rect.width * s->data.rect.height;
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long total = 0;
    for (int i = 0; i < n; i++) {
        char kind[4];
        if (scanf("%3s", kind) != 1) return 0;
        Shape s;
        if (kind[0] == 'C') {
            int r;
            if (scanf("%d", &r) != 1) return 0;
            s.tag = SHAPE_CIRCLE;
            s.data.circle.radius = r;
        } else {
            int w, h;
            if (scanf("%d %d", &w, &h) != 2) return 0;
            s.tag = SHAPE_RECT;
            s.data.rect.width = w;
            s.data.rect.height = h;
        }
        long a = shape_area(&s);
        printf("%ld\n", a);
        total += a;
    }

    printf("total=%ld\n", total);
    return 0;
}

