    int qhead = 0, qtail = 0;
    queue[qtail++] = start;
    visited[start] = 1;

    int first = 1;
    while (qhead < qtail) {
        int cur = queue[qhead++];
        if (!first) printf(" ");
        printf("%d", cur);
        first = 0;
        for (int i = 0; i < adj_count[cur]; i++) {
            int next = adj[cur][i];
            if (!visited[next]) {
