        if (*p == ' ' || *p == '\t') {
            p++;
        } else if (*p == '{' || *p == '}') {
            printf("BRACE:%c\n", *p);
            p++;
        } else if (*p == '[' || *p == ']') {
            printf("BRACKET:%c\n", *p);
            p++;
        } else if (*p == ':') {
            printf("COLON::\n");
            p++;
        } else if (*p == ',') {
            printf("COMMA:,\n");
            p++;
        } else if (*p == '"') {
            emit_string();
        } else if (isdigit((unsigned char)*p) || *p == '-') {
            emit_number();
        } else if (strncmp(p, "true", 4) == 0) {
            printf("BOOL:true\n");
            p += 4;
        } else if (strncmp(p, "false", 5) == 0) {
            printf("BOOL:false\n");
            p += 5;
        } else if (strncmp(p, "null", 4) == 0) {
            printf("NULL:null\n");
            p += 4;
        } else {
            p++;
        }
    }

    return 0;
}

