	for (int i = 0; i < n; i++) {
		scanf("%d", &arr[i]);
	}
	heapsort(arr, (size_t)n, sizeof(int), int_cmp);
	for (int i = 0; i < n; i++) {
		printf("%d%s", arr[i], (i + 1 < n) ? " " : "\n");
	}
	if (n == 0) printf("\n");
	free(arr);
	return 0;
}

