/* ---- dosya: stack.c ---- */
#include "stack.h"

void stack_init(Stack *s)
{
    s->top = -1;
}

int stack_is_empty(const Stack *s)
{
    return s->top < 0;
}

int stack_is_full(const Stack *s)
{
    return s->top >= STACK_CAPACITY - 1;
}

int stack_push(Stack *s, int value)
{
    if (stack_is_full(s)) {
        return 0;
    }
    s->data[++(s->top)] = value;
    return 1;
}

int stack_pop(Stack *s, int *out)
{
    if (stack_is_empty(s)) {
        return 0;
    }
    *out = s->data[(s->top)--];
    return 1;
}

int stack_peek(const Stack *s, int *out)
{
    if (stack_is_empty(s)) {
        return 0;
    }
    *out = s->data[s->top];
    return 1;
}

int stack_size(const Stack *s)
{
    return s->top + 1;
}


/* ---- dosya: main.c ---- */
#include <stdio.h>
#include <string.h>
#include "stack.h"

/* Girdi bicimi: ilk satir komut sayisi N, sonra N satir komut:
 *   PUSH <deger>
 *   POP
 *   PEEK
 *   SIZE
 * Her komuttan sonra sonuc bir satirda yazdirilir. */
int main(void)
{
    Stack s;
    stack_init(&s);

    int n;
    if (scanf("%d", &n) != 1) return 1;

    for (int i = 0; i < n; i++) {
        char cmd[16];
        if (scanf("%15s", cmd) != 1) break;

        if (strcmp(cmd, "PUSH") == 0) {
            int v;
            if (scanf("%d", &v) != 1) break;
            int ok = stack_push(&s, v);
            printf(ok ? "OK\n" : "FULL\n");
        } else if (strcmp(cmd, "POP") == 0) {
            int v;
            if (stack_pop(&s, &v)) {
                printf("%d\n", v);
            } else {
                printf("EMPTY\n");
            }
        } else if (strcmp(cmd, "PEEK") == 0) {
            int v;
            if (stack_peek(&s, &v)) {
                printf("%d\n", v);
            } else {
                printf("EMPTY\n");
            }
        } else if (strcmp(cmd, "SIZE") == 0) {
            printf("%d\n", stack_size(&s));
        }
    }
    return 0;
}


