        h = (h << 4) + (unsigned int)(unsigned char)buf[i];
        g = h & 0xF0000000u;
        if (g != 0) {
            h ^= g >> 24;
        }
        h &= ~g;
    }
    printf("%u\n", h);
    return 0;
