   Girdi: bir satir metin (bayt dizisi olarak islenir).
   Cikti: adler32 sonucu, ondalik (unsigned long). */

#define BASE 65521U
#define NMAX 5552

static unsigned long adler32_z(unsigned long adler, const unsigned char *buf, size_t len) {
    unsigned long sum2;
    unsigned n;

    sum2 = (adler >> 16) & 0xffff;
    adler &= 0xffff;

    if (len == 1) {
        adler += buf[0];
        if (adler >= BASE) adler -= BASE;
        sum2 += adler;
        if (sum2 >= BASE) sum2 -= BASE;
        return adler | (sum2 << 16);
    }

    if (buf == NULL) return 1L;

    if (len < 16) {
        while (len--) {
            adler += *buf++;
            sum2 += adler;
        }
        if (adler >= BASE) adler -= BASE;
        sum2 %= BASE;
        return adler | (sum2 << 16);
    }

    while (len >= NMAX) {
        len -= NMAX;
        n = NMAX / 16;
        do {
            for (int k = 0; k < 16; k++) {
                adler += *buf++;
                sum2 += adler;
            }
        } while (--n);
        adler %= BASE;
        sum2 %= BASE;
    }

    if (len) {
        while (len >= 16) {
            len -= 16;
            for (int k = 0; k < 16; k++) {
                adler += *buf++;
                sum2 += adler;
            }
        }
        while (len--) {
            adler += *buf++;
            sum2 += adler;
        }
        adler %= BASE;
        sum2 %= BASE;
    }

    return adler | (sum2 << 16);
}

