#define POLY 0xedb88320UL

static unsigned long crc_table[256];
static int table_ready = 0;

static void make_crc_table(void) {
    unsigned long c;
    int n, k;
    for (n = 0; n < 256; n++) {
        c = (unsigned long)n;
        for (k = 0; k < 8; k++) {
